def seed_default_environments(apps, schema_editor):
    """为已有项目补充默认环境, 供缺陷记录"发现环境"使用"""
    Project = apps.get_model('projects', 'Project')
    ProjectEnvironment = apps.get_model('projects', 'ProjectEnvironment')
    for project in Project.objects.all():
        if not ProjectEnvironment.objects.filter(project=project).exists():
            ProjectEnvironment.objects.create(
                project=project, name='测试环境', is_default=True, sort_order=1)


def remove_default_environments(apps, schema_editor):
    ProjectEnvironment = apps.get_model('projects', 'ProjectEnvironment')
    ProjectEnvironment.objects.filter(name='测试环境', is_default=True).delete()


